// Icons of modifiers and country values from the mods Modifier Icons and Descriptive Icons, bundled in
// assets/texticons (generated by backend hoi4dbg/texticons.py; the mods need not be installed).
import { h } from './dom.js';
import { TEXT_ICONS } from './texticons.js';

const ASSETS = 'assets/texticons/';
// modifier keys whose localisation key differs from MODIFIER_<KEY>
const ALIAS = { industrial_capacity_factory: 'industrial_capacity_factor', industrial_capacity_dockyard: 'industrial_capacity_dockyard_factor' };
// country values shown as tiles / chips (live-ui FIELD_LABELS) -> icon file
const STAT_ICONS = {
  political_power: 'political_power_texticon.png', stability: 'stability_texticon.png', war_support: 'war_support_modifiericons_texticon.png',
  command_power: 'command_power_texticon.png', fuel: 'fuel_texticon.png', manpower: 'manpower_texticon.png',
  army_experience: 'army_experience.png', navy_experience: 'navy_experience.png', air_experience: 'air_experience.png',
};

/** Icon file of a modifier key (e.g. "political_power_factor"), or null. */
export function modifierIconFile(key) {
  const k = String(key ?? '').toLowerCase();
  return TEXT_ICONS[k] ?? TEXT_ICONS[ALIAS[k]] ?? TEXT_ICONS[`modifier_${k}`] ?? null;
}

function img(file) {
  return file ? h('img', { class: 'tx-icon', src: ASSETS + file, alt: '', loading: 'lazy' }) : null;
}

/** <img> of an icon file of assets/texticons. */
export const iconImg = (file) => img(file);

/** <img> of a modifier's icon, or null when it has none. */
export const modifierIcon = (key) => img(modifierIconFile(key));

